import React, { useEffect, useRef, useState } from 'react';
import { motion } from 'framer-motion';
import { fadeIn } from '../variants';

// import logos
import vegNonVegLogo from '../img/logos/VegNonVeg.png';
import TO6Logo from '../img/logos/To6.png'
import demeLogo from '../img/logos/Deme.png'
import ModishLogo from '../img/logos/Modish.png'
import MokobaraLogo from '../img/logos/MokobaraClient.webp'
import SimbaLogo from '../img/logos/Simba.png'
import keiflogo from '../img/logos/keif.webp'
import Nail_StationLogo from '../img/logos/Nail station.png'
import DhahiaLogo from '../img/logos/Dhahia juice.png'
import Nothing from '../img/logos/Nothing_Logo.webp';
import AcquaLogo from '../img/logos/Acqua.png';
import AtyabLogo from '../img/logos/Mello.png';

import ArnavLogo from '../img/logos/arnavClient.jpg';
import AsayaLogo from '../img/logos/asayaClient.webp';
import SaykLogo from '../img/logos/Spyk.jpg';
import PhonePeLogo from '../img/logos/PhonePe.png';
import RazorPayLogo from '../img/logos/RAZORPAY.png';

const Clients = () => {
  const clientsSection = useRef();
  const [isVisible, setIsVisible] = useState(false);
  
    useEffect(() => {
      const observer = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setIsVisible(true);
            observer.unobserve(entry.target);
          }
        });
      },{
        threshold: 1
      });
  
      observer.observe(clientsSection.current);
  
      // Cleanup function
      return () => {
        observer.disconnect();
      };
    }, [clientsSection]);

    const row1Logos = [
        {
          title: '',
          image: vegNonVegLogo,
        },
        {
          title: '',
          image: TO6Logo,
        },
        {
          title: '',
          image: demeLogo,
        },
        {
          title: '',
          image: ModishLogo,
        },
        {
          title: '',
          image: MokobaraLogo,
        },
        {
          title: '',
          image: AsayaLogo,
        },
        {
          title: '',
          image: SimbaLogo,
        },
        {
          title: '',
          image: SaykLogo,
        },
        {
          title: '',
          image: PhonePeLogo,
        }
      ];
    
      const row2Logos = [
        {
          title: '',
          image: keiflogo,
        },
        {
          title: '',
          image: Nail_StationLogo,
        },
        {
          title: '',
          image: DhahiaLogo,
        },
        {
          title: '',
          image: Nothing,
        },
        {
          title: '',
          image: AcquaLogo,
        },
        {
          title: '',
          image: AtyabLogo,
        },
        {
          title: '',
          image: ArnavLogo,
        },
        {
          title: '',
          image: RazorPayLogo,
        }
      ];
  return (
    <div className='lg:flex-1 mb-8'>
              <motion.h1
              variants={fadeIn('up', 0.3)} initial="hidden"
              whileInView={'show'} viewport={{once: true, amount: 0.5}}
              className='h2'>Clients</motion.h1>
              <motion.div ref={clientsSection}
               variants={fadeIn('up', 0.3)} initial="hidden"
               whileInView={'show'} viewport={{once: true, amount: 0.5}}
               >
                    <div className='logosMarquee'>
                      {
                        isVisible && 
                        <>
                          <div className='logoMarqueeGroup1'>
                          {
                            row1Logos.map((row1Logo,index )  => (
                              <>
                                <div key={index} className='logosImageGroup'>
                                  <img className='logoImage' key={index} src={row1Logo.image} alt={''} loading='lazy'/>
                                </div>
                              </>
                            ))
                          }
                          </div>
                          <div className='logoMarqueeGroup1'>
                            {
                              row1Logos.map((row1Logo,index )  => (
                                <>
                                  <div key={index} className='logosImageGroup'>
                                    <img className='logoImage' key={index} src={row1Logo.image} alt={''} loading='lazy'/>
                                  </div>
                                </>
                              ))
                            }
                          </div>
                        </>
                      }
                  </div>
                  <div className='logosMarquee'>
                    {
                      isVisible &&
                      <>
                        <div className='logoMarqueeGroup2'>
                        {
                          row2Logos.map((row2Logo,index )  => (
                            <>
                              <div key={index}
                              className='logosImageGroup'>
                                <img className='logoImage' key={index} src={row2Logo.image} alt={''} loading='lazy'/>
                              </div>
                            </>
                          ))
                        }
                      </div>
                      <div className='logoMarqueeGroup2'>
                        {
                          row2Logos.map((row2Logo,index )  => (
                            <>
                              <div key={index}
                              className='logosImageGroup'>
                                <img className='logoImage' key={index} src={row2Logo.image} alt={''} loading='lazy'/>
                              </div>
                            </>
                          ))
                        }
                      </div>
                      </>
                    }
                  </div>
              </motion.div>
            </div>
  )
};

export default Clients;
